determinant() {
  if (!this.isSquare()) {
    throw new Error("Matrix is not square");
  }
  return this._determinantHelper(this.rows);
}

isSquare() {
  return this.rows.length === this.rows[0].length;
}

_determinantHelper(matrix) {
  if (matrix.length === 1) {
    return matrix[0][0];
  }
  if (matrix.length === 2) {
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
  }

  let determinant = 0;
  for (let col = 0; col < matrix.length; col++) {
    const subMatrix = [];
    for (let row = 1; row < matrix.length; row++) {
      const newRow = [];
      for (let c = 0; c < matrix.length; c++) {
        if (c !== col) {
          newRow.push(matrix[row][c]);
        }
      }
      subMatrix.push(newRow);
    }
    determinant += Math.pow(-1, col) * matrix[0][col] * this._determinantHelper(subMatrix);
  }
  return determinant;
}

